use crate::provenance::{CalcResult,VerificationStatus};
use std::collections::BTreeMap;
#[derive(Clone,serde::Serialize,serde::Deserialize)] pub struct OpticalBounds { pub critical_angle_deg:f64,pub trap_fraction:CalcResult,pub lsc_efficiency:Option<CalcResult> }
pub fn optical_bounds(n_core:f64,n_clad:f64,lsc:Option<(f64,VerificationStatus)>)->OpticalBounds { let ratio=(n_clad/n_core).clamp(0.0,1.0); let mut i=BTreeMap::new();i.insert("n_core".into(),n_core);i.insert("n_clad".into(),n_clad); let f=(1.0-ratio*ratio).sqrt(); let mut trap=CalcResult::new("theoretical_geometric_trapping_upper_bound",f,"fraction","sqrt(1-(n_clad/n_core)^2)",i,VerificationStatus::Calculated); trap.assumptions.push("Theoretical upper bound; not system efficiency".into()); let lsc_efficiency=lsc.map(|(v,s)|CalcResult::new("eta_LSC",v,"fraction","user supplied or measured system efficiency",BTreeMap::new(),s)); OpticalBounds{critical_angle_deg:ratio.asin().to_degrees(),trap_fraction:trap,lsc_efficiency} }
#[derive(Clone,serde::Serialize,serde::Deserialize)] pub struct RaySegment {pub start:[f64;3],pub end:[f64;3],pub tir:bool}
pub fn run_monte_carlo_tracer(rays:usize,n_core:f64,n_clad:f64,thickness:f64,length:f64)->Vec<RaySegment>{ let mut out=Vec::with_capacity(rays); let critical=(n_clad/n_core).clamp(0.0,1.0).asin(); for i in 0..rays { let u=((i as f64+0.5)/rays.max(1) as f64).fract(); let v=((i as f64*0.61803398875).fract()); let theta=(1.0-2.0*u).acos(); let phi=2.0*std::f64::consts::PI*v; let d=[theta.sin()*phi.cos(),theta.sin()*phi.sin(),theta.cos()]; let start=[length*(v-0.5),thickness*(u-0.5),0.0]; let end=[start[0]+d[0]*length*0.2,start[1]+d[1]*thickness*0.2,start[2]+d[2]*length*0.2]; out.push(RaySegment{start,end,tir:d[2].abs()>critical.sin()}); } out }
